#!/bin/bash
#================================================================================================
#	This script is for creating simple LLM friendly language files in *.txt format
#	Uses language *.ts files generated by cmake.
#	Edit the variables given at the top to your liking.
#	Multi-line strings are flattened to one line using &#10; as the newline marker.
#================================================================================================
InputDir=../languages
OutputDir=~/Desktop/languagesOUT
Prompt='Translate every translation line into %s using the source line above it. \nPreserve the format, XML escapes and every &#10; marker (it means a line break).\n\n'
#================================================================================================

# Locale-to-language names. Unknown locales fall back to their locale code.
language_name() {
    case "$1" in
        af*) echo "Afrikaans" ;;
        ar*) echo "Arabic" ;;
        bg*) echo "Bulgarian" ;;
        bn*) echo "Bengali" ;;
        ca*) echo "Catalan" ;;
        cs*) echo "Czech" ;;
        da*) echo "Danish" ;;
        de*) echo "German" ;;
        el*) echo "Greek" ;;
        en*) echo "English" ;;
        es*) echo "Spanish" ;;
        et*) echo "Estonian" ;;
        fa*) echo "Persian" ;;
        fi*) echo "Finnish" ;;
        fr*) echo "French" ;;
        he*|iw*) echo "Hebrew" ;;
        hi*) echo "Hindi" ;;
        hr*) echo "Croatian" ;;
        hu*) echo "Hungarian" ;;
        id*) echo "Indonesian" ;;
        it*) echo "Italian" ;;
        ja*) echo "Japanese" ;;
        ko*) echo "Korean" ;;
        lt*) echo "Lithuanian" ;;
        lv*) echo "Latvian" ;;
        ms*) echo "Malay" ;;
        nb*|no*) echo "Norwegian" ;;
        nl*) echo "Dutch" ;;
        pl*) echo "Polish" ;;
        pt*) echo "Portuguese" ;;
        ro*) echo "Romanian" ;;
        ru*) echo "Russian" ;;
        sk*) echo "Slovak" ;;
        sl*) echo "Slovenian" ;;
        sr*) echo "Serbian" ;;
        sv*) echo "Swedish" ;;
        th*) echo "Thai" ;;
        tr*) echo "Turkish" ;;
        uk*) echo "Ukrainian" ;;
        ur*) echo "Urdu" ;;
        vi*) echo "Vietnamese" ;;
        zh*) echo "Chinese" ;;
        *)   echo "$1" ;;
    esac
}

if [[ ! -d "$InputDir" ]]; then
    printf 'Error: input directory not found: %s\n' "$InputDir" >&2
    exit 1
fi

mkdir -p "$OutputDir" || exit 1
shopt -s nullglob
files=("$InputDir"/*.ts)

if (( ${#files[@]} == 0 )); then
    printf 'No .ts files found in: %s\n' "$InputDir"
    exit 0
fi

for ts_file in "${files[@]}"; do
    filename="${ts_file##*/}"
    basename="${filename%.ts}"
    txt_file="$OutputDir/$basename.txt"

    # Read the locale from the TS root element, e.g. language="tr_TR".
    locale=$(sed -n 's/.*language="\([^"]*\)".*/\1/p' "$ts_file" | head -n 1)
    [[ -n "$locale" ]] || locale="${basename##*_}"
    language=$(language_name "$locale")

    {
        printf "$Prompt" "$language"

        # Elements may span several lines. Collect everything up to the closing tag,
        # join the lines with &#10; and emit the compact delimiter format.
        awk '
            function emit(t, txt) {
                print "<" t ">" txt "<"
                if (t == "translation") print ""
            }
            {
                line = $0
                sub(/\r$/, "", line)
                if (!inside) {
                    if (match(line, /<(source|translation)[[:space:]>]/)) {
                        tag = substr(line, RSTART + 1, RLENGTH - 2)
                        line = substr(line, RSTART + RLENGTH - 1)
                        sub(/^[^>]*>/, "", line)
                        buf = ""
                        started = 0
                        inside = 1
                    } else {
                        next
                    }
                }
                endtag = "</" tag ">"
                p = index(line, endtag)
                piece = (p ? substr(line, 1, p - 1) : line)
                buf = (started ? buf "&#10;" piece : piece)
                started = 1
                if (p) {
                    emit(tag, buf)
                    inside = 0
                }
            }
        ' "$ts_file"
    } > "$txt_file"

    printf 'Created: %s\n' "$txt_file"
done
